9	export interface TranslationAdapter {
10	  readonly name: string;
11	  /**
12	   * Whether this adapter produces real prose translations. The glossary sets this `false`: it only
13	   * knows structural terms, so the pipeline must not treat its passthrough of a prose block as a
14	   * translation (see the poison-cache guard in {@link ./translation-memory.ts}). Defaults to `true`.
15	   */
16	  readonly translatesProse?: boolean;
17	  translateMarkdown(input: string, filePath: string): Promise<string>;
18	  translateText(input: string): Promise<string>;
19	  /**
20	   * Translate many short strings in one request. Returns a map keyed by each item's `id`. Optional:
21	   * callers fall back to per-item {@link TranslationAdapter.translateText} when it's absent.
22	   *
23	   * `onChunk` (if given) is called with each chunk's partial results as it completes, so a caller can
24	   * persist and report progress mid-run rather than only after the whole batch returns. Chunks may
25	   * run concurrently, so `onChunk` can fire out of order.
26	   */
27	  translateBatch?(
28	    items: readonly { id: string; text: string }[],
29	    onChunk?: (partial: Record<string, string>) => void,
30	  ): Promise<Record<string, string>>;
31	}
