136	export class GlossaryTranslationAdapter implements TranslationAdapter {
137	  readonly name = "glossary";
138	  // Deterministic term substitution only — it cannot translate prose, so the memory must never cache
139	  // its output under a prose key.
140	  readonly translatesProse = false;
141	
142	  translateMarkdown(input: string): Promise<string> {
143	    return Promise.resolve(translateWithoutFencedCode(input, (text) => this.translateSync(text)));
144	  }
145	
146	  translateText(input: string): Promise<string> {
147	    return Promise.resolve(this.translateSync(input));
148	  }
149	
150	  /** The deterministic core — synchronous; the async methods just wrap it to satisfy the contract. */
151	  private translateSync(input: string): string {
152	    const preserved = preservePackageNames(input);
153	    let out = preserved.text;
154	    for (const [pattern, value] of SORTED_REPLACEMENTS) {
155	      out = out.replace(pattern, value);
156	    }
157	    return restorePackageNames(out, preserved.packageNames);
158	  }
159	
160	  translateBatch(
161	    items: readonly { id: string; text: string }[],
162	    onChunk?: (partial: Record<string, string>) => void,
163	  ): Promise<Record<string, string>> {
164	    const out = Object.fromEntries(items.map((item) => [item.id, this.translateSync(item.text)]));
165	    onChunk?.(out);
166	    return Promise.resolve(out);
167	  }
168	}
169	
170	const replaceBlocks = (
171	  input: string,
172	  pattern: RegExp,
173	  markerPrefix: string,
174	): { text: string; blocks: string[] } => {
175	  const blocks: string[] = [];
176	  const text = input.replace(pattern, (match) => {
177	    const marker = `__${markerPrefix}_${blocks.length}__`;
178	    blocks.push(match);
179	    return marker;
180	  });
181	  return { text, blocks };
182	};
183	
184	const restoreBlocks = (input: string, blocks: string[], markerPrefix: string): string => {
185	  let out = input;
186	  for (const [index, block] of blocks.entries()) {
187	    out = out.replaceAll(`__${markerPrefix}_${index}__`, block);
188	  }
189	  return out;
190	};
191	
192	const preserveMarkdownSensitiveBlocks = (
193	  input: string,
194	): {
195	  text: string;
196	  codeBlocks: string[];
197	  inlineCodeBlocks: string[];
198	} => {
199	  const fenced = replaceBlocks(input, /```[\s\S]*?```/g, "PTK_CODE_BLOCK");
200	  const inline = replaceBlocks(fenced.text, /`[^`\n]+`/g, "PTK_INLINE_CODE");
201	  return {
202	    text: inline.text,
203	    codeBlocks: fenced.blocks,
204	    inlineCodeBlocks: inline.blocks,
205	  };
206	};
207	
208	const restoreMarkdownSensitiveBlocks = (
209	  input: string,
210	  codeBlocks: string[],
211	  inlineCodeBlocks: string[],
212	): string => {
213	  const withCode = restoreBlocks(input, codeBlocks, "PTK_CODE_BLOCK");
214	  return restoreBlocks(withCode, inlineCodeBlocks, "PTK_INLINE_CODE");
215	};
216	
217	const preservePackageNames = (input: string): { text: string; packageNames: string[] } => {
218	  const packagePattern = /@[a-z0-9][a-z0-9.-]*\/[a-z0-9][a-z0-9.-]*/gi;
219	  const packageNames: string[] = [];
220	
221	  const text = input.replace(packagePattern, (match) => {
222	    const marker = `__PTK_PACKAGE_${packageNames.length}__`;
223	    packageNames.push(match);
224	    return marker;
225	  });
226	
227	  return { text, packageNames };
228	};
229	
230	/** Pull the first `{…}` JSON object out of a model response (tolerating code fences), or `null`. */
231	const extractJsonObject = (raw: string): Record<string, unknown> | null => {
232	  const start = raw.indexOf("{");
233	  const end = raw.lastIndexOf("}");
234	  if (start === -1 || end <= start) return null;
235	  try {
236	    const parsed = JSON.parse(raw.slice(start, end + 1)) as unknown;
237	    return typeof parsed === "object" && parsed !== null
238	      ? (parsed as Record<string, unknown>)
239	      : null;
240	  } catch {
241	    return null;
242	  }
243	};
244	
245	const restorePackageNames = (input: string, packageNames: string[]): string => {
246	  let out = input;
247	  for (const [index, packageName] of packageNames.entries()) {
248	    out = out.replaceAll(`__PTK_PACKAGE_${index}__`, packageName);
249	  }
250	  return out;
251	};
252	
253	const translateWithoutFencedCode = (input: string, translate: (line: string) => string): string => {
254	  const lines = input.split("\n");
255	  const out: string[] = [];
256	  let inFence = false;
257	
258	  for (const line of lines) {
259	    if (line.trimStart().startsWith("```")) {
260	      inFence = !inFence;
261	      out.push(line);
262	      continue;
263	    }
264	
265	    if (inFence) {
266	      out.push(line);
267	      continue;
268	    }
269	
270	    out.push(translate(line));
271	  }
272	
273	  return out.join("\n");
274	};
275	
276	/** Run `tasks` with at most `limit` in flight at once, preserving result order. */
277	const mapPool = async <T, R>(
278	  tasks: readonly T[],
279	  limit: number,
280	  fn: (task: T, index: number) => Promise<R>,
281	): Promise<R[]> => {
282	  const results: R[] = Array.from({ length: tasks.length });
283	  let next = 0;
284	  const worker = async (): Promise<void> => {
285	    while (next < tasks.length) {
286	      const index = next++;
287	      results[index] = await fn(tasks[index], index);
288	    }
289	  };
290	  await Promise.all(Array.from({ length: Math.min(limit, tasks.length) }, worker));
291	  return results;
292	};
293	
294	export class ClaudeCodeTranslationAdapter implements TranslationAdapter {
295	  readonly name = "claude-code";
296	
297	  private readonly command: string;
298	  private readonly args: string[];
299	
300	  constructor() {
301	    this.command = process.env.DOCS_TRANSLATION_COMMAND ?? "claude";
302	    this.args = (process.env.DOCS_TRANSLATION_COMMAND_ARGS ?? "")
303	      .split(" ")
304	      .map((part) => part.trim())
305	      .filter((part) => part.length > 0);
306	  }
307	
308	  async translateMarkdown(input: string, filePath: string): Promise<string> {
309	    const preservedMarkdown = preserveMarkdownSensitiveBlocks(input);
310	    const preservedPackages = preservePackageNames(preservedMarkdown.text);
311	    const prompt = [
312	      "Translate this technical markdown from English to Hungarian.",
313	      "Return only the translated markdown.",
314	      "Rules:",
315	      "- Keep markdown structure unchanged.",
316	      "- Do not alter placeholder tokens like __PTK_CODE_BLOCK_#__ or __PTK_INLINE_CODE_#__.",
317	      "- Do not alter placeholder tokens like __PTK_PACKAGE_#__.",
318	      "- Preserve whitespace and line breaks.",
319	      "- Keep import paths, package names, URLs, and identifiers intact.",
320	      `File: ${filePath}`,
321	      "--- BEGIN MARKDOWN ---",
322	      preservedPackages.text,
323	      "--- END MARKDOWN ---",
324	    ].join("\n");
325	
326	    const translated = await this.runClaude(prompt, `markdown file ${filePath}`);
327	    const restoredPackages = restorePackageNames(translated, preservedPackages.packageNames);
328	    return restoreMarkdownSensitiveBlocks(
329	      restoredPackages,
330	      preservedMarkdown.codeBlocks,
331	      preservedMarkdown.inlineCodeBlocks,
332	    );
333	  }
334	
335	  async translateText(input: string): Promise<string> {
336	    const preserved = preservePackageNames(input);
337	    const prompt = [
338	      "Translate this technical UI text from English to Hungarian.",
339	      "Return only the translation.",
340	      "Keep identifiers and package names unchanged.",
341	      "Do not alter placeholder tokens like __PTK_PACKAGE_#__.",
342	      "Text:",
343	      preserved.text,
344	    ].join("\n");
345	
346	    const translated = (await this.runClaude(prompt, "single text line")).trim();
347	    return restorePackageNames(translated, preserved.packageNames);
348	  }
349	
350	  async translateBatch(
351	    items: readonly { id: string; text: string }[],
352	    onChunk?: (partial: Record<string, string>) => void,
353	  ): Promise<Record<string, string>> {
354	    // Split into character-budgeted chunks. Each chunk is one `claude -p` call; because the run is
355	    // generation-bound (the model streaming ~a chunk's worth of translations dominates the fixed
356	    // startup), running several chunks concurrently is the real wall-clock lever. Smaller chunks keep
357	    // each JSON response reliable and give finer progress; the pool hides their startup cost.
358	    const BUDGET = Number(process.env.DOCS_TRANSLATION_BATCH_BUDGET) || 4000;
359	    const CONCURRENCY = Number(process.env.DOCS_TRANSLATION_CONCURRENCY) || 5;
360	    const chunks: { id: string; text: string }[][] = [];
361	    let chunk: { id: string; text: string }[] = [];
362	    let size = 0;
363	    for (const item of items) {
364	      if (size + item.text.length > BUDGET && chunk.length > 0) {
365	        chunks.push(chunk);
366	        chunk = [];
367	        size = 0;
368	      }
369	      chunk.push(item);
370	      size += item.text.length;
371	    }
372	    if (chunk.length > 0) chunks.push(chunk);
373	
374	    const out: Record<string, string> = {};
375	    await mapPool(chunks, CONCURRENCY, async (group) => {
376	      // A failed chunk must not sink the whole run or poison the cache: log it and skip. Its items go
377	      // uncached (the caller leaves them as source), so they're retried on the next run.
378	      try {
379	        const partial = await this.runBatch(group);
380	        Object.assign(out, partial);
381	        // Surface each chunk as it lands so the caller can persist + report progress.
382	        onChunk?.(partial);
383	      } catch (error) {
384	        console.warn(
385	          `  ! skipped a batch of ${group.length} strings: ${error instanceof Error ? error.message : String(error)}`,
386	        );
387	      }
388	    });
389	    return out;
390	  }
391	
392	  /** Translate one chunk of short strings as a single JSON object; fall back per item on failure. */
393	  private async runBatch(
394	    items: readonly { id: string; text: string }[],
395	  ): Promise<Record<string, string>> {
396	    // Protect code and package names in every value before it reaches the model — prose cells and
397	    // captions carry inline code and `@scope/pkg` names that must survive verbatim — then restore per
398	    // id. Without this the batch path (unlike translateMarkdown) would let the model rewrite them.
399	    const masked = items.map((item) => {
400	      const markdown = preserveMarkdownSensitiveBlocks(item.text);
401	      const packages = preservePackageNames(markdown.text);
402	      return { id: item.id, masked: packages.text, markdown, packages };
403	    });
404	    const restore = (entry: (typeof masked)[number], value: string): string =>
405	      restoreMarkdownSensitiveBlocks(
406	        restorePackageNames(value, entry.packages.packageNames),
407	        entry.markdown.codeBlocks,
408	        entry.markdown.inlineCodeBlocks,
409	      );
410	
411	    const payload = Object.fromEntries(masked.map((entry) => [entry.id, entry.masked]));
412	    const prompt = [
413	      "Translate the VALUES of this JSON object from English to Hungarian.",
414	      "Return ONLY a JSON object with the same keys and translated values.",
415	      "Do not translate, add, or remove keys. Keep identifiers, package names, and URLs unchanged.",
416	      "Do not alter placeholder tokens like __PTK_CODE_BLOCK_#__, __PTK_INLINE_CODE_#__, or __PTK_PACKAGE_#__.",
417	      JSON.stringify(payload, null, 2),
418	    ].join("\n");
419	
420	    const raw = await this.runClaude(prompt, `batch of ${items.length} strings`);
421	    const parsed = extractJsonObject(raw);
422	    if (parsed) {
423	      const out: Record<string, string> = {};
424	      for (const entry of masked) {
425	        const value = parsed[entry.id];
426	        // A missing/non-string value restores to the (masked → original) source rather than dropping it.
427	        out[entry.id] = restore(entry, typeof value === "string" ? value : entry.masked);
428	      }
429	      return out;
430	    }
431	    // The model didn't return usable JSON; degrade to per-item translation rather than lose content.
432	    const out: Record<string, string> = {};
433	    for (const item of items) out[item.id] = await this.translateText(item.text);
434	    return out;
435	  }
436	
437	  private runClaude(prompt: string, scope: string): Promise<string> {
438	    return new Promise((resolve, reject) => {
439	      const child = spawn(this.command, [...this.args, "-p"], {
440	        stdio: ["pipe", "pipe", "pipe"],
441	      });
442	      let stdout = "";
443	      let stderr = "";
444	      child.stdout.setEncoding("utf8");
445	      child.stderr.setEncoding("utf8");
446	      child.stdout.on("data", (chunk: string) => (stdout += chunk));
447	      child.stderr.on("data", (chunk: string) => (stderr += chunk));
448	      // The process-level events (`error`/`close`) come off ChildProcess's EventEmitter; type them
449	      // explicitly so the checker resolves the overloads and `code` isn't implicitly `any`.
450	      const proc = child as unknown as {
451	        on(event: "error", listener: (err: Error) => void): void;
452	        on(event: "close", listener: (code: number | null) => void): void;
453	      };
454	      proc.on("error", reject);
455	      proc.on("close", (code) => {
456	        if (code !== 0) {
457	          reject(
458	            new Error(
459	              `Claude translation failed for ${scope} (exit ${code ?? -1}): ${stderr.trim()}`,
460	            ),
461	          );
462	        } else {
463	          resolve(stdout.trimEnd());
464	        }
465	      });
466	      child.stdin.end(prompt);
467	    });
468	  }
469	}
470	
471	export const createTranslationAdapter = (): TranslationAdapter => {
472	  // A pluggable selector means we can drop in a richer provider later without changing callers.
473	  const selected = (process.env.DOCS_TRANSLATION_ADAPTER ?? "glossary").toLowerCase();
474	
475	  if (selected === "glossary") {
476	    return new GlossaryTranslationAdapter();
477	  }
478	
479	  if (selected === "claude-code") {
480	    return new ClaudeCodeTranslationAdapter();
481	  }
482	
483	  throw new Error(
484	    `Unsupported DOCS_TRANSLATION_ADAPTER: ${selected}. Supported adapters: glossary, claude-code`,
485	  );
486	};
